namespace MiraAPI.Hud;

/// <summary>
/// Custom button manager for handling custom buttons.
/// </summary>
public static class CustomButtonManager
{
    /// <summary>
    /// Gets a list of all registered custom buttons.
    /// </summary>
    public static ReadOnlyCollection<CustomActionButton> Buttons { get; internal set; } = new([]);

    internal static readonly List<CustomActionButton> CustomButtons = [];
    internal static readonly Dictionary<Type, Type> ButtonEventTypes = [];
    internal static readonly Dictionary<Type, Type> ButtonCancelledEventTypes = [];

    internal static bool RegisterButton(Type buttonType, MiraPluginInfo pluginInfo)
    {
        if (!buttonType.IsAssignableTo(typeof(CustomActionButton)) || Activator.CreateInstance(buttonType) is not CustomActionButton button)
        {
            return false;
        }

        CustomButtons.Add(button);
        pluginInfo.InternalButtons.Add(button);
        typeof(CustomButtonSingleton<>).MakeGenericType(buttonType)
#pragma warning disable S3011
            .GetField("_instance", BindingFlags.Static | BindingFlags.NonPublic)!
#pragma warning restore S3011
            .SetValue(null, button);

        ButtonEventTypes.Add(buttonType, typeof(MiraButtonClickEvent<>).MakeGenericType(buttonType));
        ButtonCancelledEventTypes.Add(buttonType, typeof(MiraButtonCancelledEvent<>).MakeGenericType(buttonType));

        return true;
    }
}

using HarmonyLib;
using InnerNet;
using MiraAPI.Roles;
using Reactor.Utilities.Extensions;

namespace MiraAPI.Patches.Roles;

/// <summary>
/// HudManager patches for roles.
/// </summary>
[HarmonyPatch(typeof(HudManager))]
public static class HudManagerPatches
{
    // Custom role tab.
    public static TaskPanelBehaviour? RoleTab;

    /// <summary>
    /// Fixes Kill Button not showing for Neutral killing role.
    /// </summary>
    /// <param name="__instance">HudManager instance.</param>
    /// <param name="localPlayer">The local PlayerControl.</param>
    /// <param name="role">The player's RoleBehaviour.</param>
    /// <param name="isActive">Whether the Hud should be set active or not.</param>
    [HarmonyPostfix]
    [HarmonyPatch(nameof(HudManager.SetHudActive), typeof(PlayerControl), typeof(RoleBehaviour), typeof(bool))]
    public static void SetHudActivePostfix(
        HudManager __instance,
        PlayerControl localPlayer,
        RoleBehaviour role,
        bool isActive)
    {
        var flag = localPlayer.Data != null && localPlayer.Data.IsDead;

        if (role is ICustomRole customRole)
        {
            __instance.KillButton.ToggleVisible(isActive && customRole.Configuration.UseVanillaKillButton && !flag);
            __instance.ImpostorVentButton.ToggleVisible(isActive && customRole.Configuration.CanUseVent && !flag);
            __instance.SabotageButton.gameObject.SetActive(isActive && customRole.Configuration.CanUseSabotage);
        }

        if (RoleTab)
        {
            RoleTab?.gameObject.SetActive(isActive);
        }
    }

    /// <summary>
    /// Update custom role tab and custom role hud elements.
    /// </summary>
    [HarmonyPostfix]
    [HarmonyPatch(nameof(HudManager.Update))]
    public static void UpdatePostfix(HudManager __instance)
    {
        var local = PlayerControl.LocalPlayer;

        if (AmongUsClient.Instance.GameState != InnerNetClient.GameStates.Started && !ShipStatus.Instance)
        {
            return;
        }

        var role = local?.Data?.Role;

        if (role is ICustomRole { Configuration.RoleHintType: RoleHintType.RoleTab } customRole)
        {
            if (RoleTab == null)
            {
                RoleTab = CustomRoleManager.CreateRoleTab(customRole);
            }

            CustomRoleManager.UpdateRoleTab(RoleTab, customRole);
        }
        else if (RoleTab)
        {
            RoleTab?.gameObject.Destroy();
        }
    }
}

